410	    emit(latest.copyWith(sessionId: maybeId));
411	
412	    final stream = _chatRepository.sendMessage(
413	      sessionId: maybeId,
414	      content: userMessage.content,
415	    );
416	    await _consumeTurn(
417	      stream,
418	      emit,
419	      generation: generation,
420	      sessionId: maybeId,
421	      optimisticUserId: userMessage.id,
422	      optimisticAssistantId: placeholder.id,
423	    );
424	  }
425	
426	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
427	  /// and a retry.
428	  Future<void> _consumeTurn(
429	    Stream<Either<Failure, ChatStreamEvent>> stream,
430	    Emitter<ChatState> emit, {
431	    required int generation,
432	    required String sessionId,
433	    required String? optimisticUserId,
434	    required String optimisticAssistantId,
435	  }) async {
436	    var assistantId = optimisticAssistantId;
437	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
438	      stream,
439	      onData: (result) {
440	        final latest = state;
441	        if (generation != _turnGeneration || latest is! ChatReady) {
442	          return latest;
443	        }
444	        return result.match((failure) {
445	          if (failure is AuthExpiredFailure) _reauthController.add(null);
446	          return _applyFailure(latest, assistantId, failure);
447	        }, (event) => switch (event) {
448	          MessageCreated() => () {
449	            assistantId = event.assistantMessageId;
450	            return _reconcileIds(
451	              latest,
452	              optimisticUserId,
453	              event.userMessageId,
454	              optimisticAssistantId,
455	              event.assistantMessageId,
456	            );
457	          }(),
458	          ContextReceived() => latest,
459	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
460	          StreamDone(assistantMessageId: final id) =>
461	            _completeMessage(latest, id).copyWith(awaitingResponse: false),
462	        });
463	      },
464	    );
465	    await _reconcileSilentFailure(emit, sessionId, assistantId, generation);
466	  }
467	
468	  /// A failure yielded as (or before) the stream's very first item leaves the
469	  /// bubble `failed` with empty content even though the backend may have
470	  /// kept generating in the background and already persisted the full
471	  /// answer by the time the stream closed (e.g. a transient network drop
472	  /// right after `message_created`, before any token arrives). One
473	  /// best-effort refetch here closes that gap without needing the user to
474	  /// leave and come back. Only acts on an empty-content failure — a failure
475	  /// after partial tokens (FR-005) is left exactly as the stream reported
476	  /// it. Note this is a best-effort recovery for a genuinely slow backend,
477	  /// not a substitute for parsing the stream correctly in the first place —
478	  /// it loses the race whenever the backend is still generating (slow/live
479	  /// answers can take several seconds longer than this one refetch waits
480	  /// for).
481	  Future<void> _reconcileSilentFailure(
482	    Emitter<ChatState> emit,
483	    String sessionId,
484	    String assistantId,
485	    int generation,
486	  ) async {
487	    final seeded = state;
488	    if (seeded is! ChatReady || generation != _turnGeneration) return;
489	    final index = seeded.messages.indexWhere((m) => m.id == assistantId);
490	    if (index == -1) return;
491	    final message = seeded.messages[index];
492	    if (message.status != ChatMessageStatus.failed || message.content.isNotEmpty) {
493	      return;
494	    }
495	
496	    final result = await _chatRepository.listMessages(sessionId);
497	    if (generation != _turnGeneration) return;
498	    result.match((_) {}, (serverMessages) {
499	      ChatMessage? persisted;
500	      for (final m in serverMessages) {
501	        if (m.role == ChatRole.assistant && m.seq == message.seq) {
502	          persisted = m;
503	          break;
504	        }
505	      }
506	      final resolved = persisted;
507	      if (resolved == null ||
508	          resolved.status != ChatMessageStatus.complete ||
509	          resolved.content.isEmpty) {
510	        return;
511	      }
512	      final latest = state;
513	      if (latest is! ChatReady || generation != _turnGeneration) return;
514	      final updated = [
515	        for (final m in latest.messages) if (m.id == assistantId) resolved else m,
516	      ];
517	      emit(latest.copyWith(messages: updated));
518	    });
519	  }
520	
521	  void _failTurn(
522	    Emitter<ChatState> emit,
523	    String assistantId,
524	    Failure failure,
525	  ) {
526	    final latest = state;
527	    if (latest is! ChatReady) return;
528	    emit(_applyFailure(latest, assistantId, failure));
529	  }
530	
531	  /// `null` for a retry's `userMessageId` — a retry never targets an
532	  /// optimistic question, only an already-persisted one.
533	  ChatReady _reconcileIds(
534	    ChatReady current,
535	    String? optimisticUserId,
536	    String realUserId,
537	    String optimisticAssistantId,
538	    String realAssistantId,
539	  ) {
540	    final updated = [
541	      for (final m in current.messages)
542	        if (optimisticUserId != null && m.id == optimisticUserId)
543	          _withId(m, realUserId)
544	        else if (m.id == optimisticAssistantId)
545	          _withId(m, realAssistantId)
546	        else
547	          m,
548	    ];
549	    return current.copyWith(messages: updated);
550	  }
551	
552	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
553	    id: id,
554	    sessionId: message.sessionId,
555	    role: message.role,
556	    content: message.content,
557	    seq: message.seq,
558	    status: message.status,
559	    retryCount: message.retryCount,
560	    createdAt: message.createdAt,
561	  );
562	
563	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
564	    final updated = [
565	      for (final m in current.messages)
566	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
567	    ];
568	    return current.copyWith(messages: updated);
569	  }
570	
571	  // The backend's `done` SSE event carries no authoritative `content`
572	  // (contracts/zod/chat.ts's `sseDoneEventSchema` has only
573	  // `assistantMessageId`/`finishReason`) — the message's own content, built
574	  // up from this turn's `TokenReceived` deltas, is already the full answer.
575	  ChatReady _completeMessage(ChatReady current, String assistantId) {
576	    final updated = [
577	      for (final m in current.messages)
578	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.complete) else m,
579	    ];
580	    return current.copyWith(messages: updated);
581	  }
582	
583	  /// Keeps whatever partial `content` had already accumulated — never
584	  /// removed, hidden, or blanked (FR-005).
585	  ChatReady _applyFailure(
586	    ChatReady current,
587	    String assistantId,
588	    Failure failure,
589	  ) {
590	    final updated = [
591	      for (final m in current.messages)
592	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
593	    ];
594	    return current.copyWith(messages: updated, awaitingResponse: false);
595	  }
596	
597	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
598	    id: message.id,
599	    sessionId: message.sessionId,
600	    role: message.role,
601	    content: content,
602	    seq: message.seq,
603	    status: message.status,
604	    retryCount: message.retryCount,
605	    createdAt: message.createdAt,
606	  );
607	
608	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
609	      ChatMessage(
610	        id: message.id,
611	        sessionId: message.sessionId,
612	        role: message.role,
613	        content: message.content,
614	        seq: message.seq,
615	        status: status,
616	        retryCount: message.retryCount,
617	        createdAt: message.createdAt,
618	      );
619	
620	  /// Position-matching (research.md R10) — the id of the user message
621	  /// immediately preceding [message] in [messages], or `null` if it isn't
622	  /// immediately preceded by one.
623	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
624	    final index = messages.indexWhere((m) => m.id == message.id);
625	    if (index <= 0) return null;
626	    final preceding = messages[index - 1];
627	    return preceding.role == ChatRole.user ? preceding.id : null;
628	  }
629	
630	  @override
631	  Future<void> close() {
632	    unawaited(_connectivitySubscription.cancel());
633	    unawaited(_reauthController.close());
634	    return super.close();
635	  }
636	}
