import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
import 'package:flutter/material.dart';

/// Renders one icon/spinner per [BookmarkStatus] (research.md R7/R8). The
/// `GestureDetector` is omitted entirely (not merely disabled) for
/// `saving`/`saved` — FR-003's literal "carries no tap handler".
class BookmarkButton extends StatelessWidget {
  const BookmarkButton({required this.status, this.onTap, super.key});

  final BookmarkStatus status;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final Widget icon = switch (status) {
      BookmarkStatus.idle => const Icon(
        Icons.bookmark_border,
        size: DesignTokens.sizeBookmarkIcon,
        color: DesignTokens.colorTextSecondary,
      ),
      BookmarkStatus.saving => const _BookmarkSpinner(),
      BookmarkStatus.saved => const Icon(
        Icons.check,
        size: DesignTokens.sizeBookmarkIcon,
        color: DesignTokens.colorAccent,
      ),
      BookmarkStatus.error => const Icon(
        Icons.error_outline,
        size: DesignTokens.sizeBookmarkIcon,
        color: DesignTokens.colorError,
      ),
    };

    switch (status) {
      case BookmarkStatus.saving:
      case BookmarkStatus.saved:
        return icon;
      case BookmarkStatus.idle:
      case BookmarkStatus.error:
        return GestureDetector(onTap: onTap, child: icon);
    }
  }
}

/// `CaptureLoadingIndicator`'s rotating-arc technique, resized to
/// [DesignTokens.sizeBookmarkIcon].
class _BookmarkSpinner extends StatefulWidget {
  const _BookmarkSpinner();

  @override
  State<_BookmarkSpinner> createState() => _BookmarkSpinnerState();
}

class _BookmarkSpinnerState extends State<_BookmarkSpinner>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this, duration: const Duration(seconds: 1))
      ..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: DesignTokens.sizeBookmarkIcon,
      height: DesignTokens.sizeBookmarkIcon,
      child: RotationTransition(
        turns: _controller,
        child: const CircularProgressIndicator(
          strokeWidth: DesignTokens.strokeWidthLoadingIndicator,
          value: DesignTokens.valueLoadingIndicatorArc,
          color: DesignTokens.colorTextSecondary,
        ),
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
import 'package:cerne/features/chat/domain/entities/chat_message.dart';
import 'package:cerne/features/chat/presentation/widgets/bookmark_button.dart';
import 'package:flutter/material.dart';

/// One widget, branching on [ChatMessage.role]/[ChatMessage.status]
/// (data-model.md). `streaming` → a blinking cursor appended inline at the
/// end of the (possibly still-empty) bubble text, nothing below the bubble,
/// not tappable; `complete` → the bubble plus a small, gray, monospaced
/// timestamp below it; `failed` → "Falha ao gerar resposta — toque para
/// tentar novamente" in small red (regular, not monospaced) text below the
/// bubble, with the same timestamp still below that, tappable only in this
/// state (FR-004/FR-006).
class ChatMessageBubble extends StatelessWidget {
  const ChatMessageBubble({
    required this.message,
    this.onRetryTap,
    this.bookmarkStatus,
    this.onBookmarkTap,
    super.key,
  });

  final ChatMessage message;
  final VoidCallback? onRetryTap;

  /// Only ever read inside the `_isUser` branch — the assistant branch never
  /// instantiates [BookmarkButton] (FR-001 holds by construction).
  final BookmarkStatus? bookmarkStatus;
  final VoidCallback? onBookmarkTap;

  bool get _isUser => message.role == ChatRole.user;

  @override
  Widget build(BuildContext context) {
    final isFailed = message.status == ChatMessageStatus.failed;

    final bubble = Container(
      margin: const EdgeInsets.symmetric(horizontal: DesignTokens.spacingMd),
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      constraints: BoxConstraints(maxWidth: MediaQuery.of(context).size.width * 0.8),
      decoration: BoxDecoration(
        color: _isUser ? DesignTokens.colorChatBubbleUser : DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.only(
          topLeft: const Radius.circular(DesignTokens.radiusMd),
          topRight: const Radius.circular(DesignTokens.radiusMd),
          bottomLeft: Radius.circular(_isUser ? DesignTokens.radiusMd : 0),
          bottomRight: Radius.circular(_isUser ? 0 : DesignTokens.radiusMd),
        ),
        boxShadow: _isUser ? null : DesignTokens.elevation1,
      ),
      child: Text.rich(
        TextSpan(
          text: message.content,
          children: [
            if (message.status == ChatMessageStatus.streaming)
              const WidgetSpan(
                alignment: PlaceholderAlignment.middle,
                child: _StreamingCursor(),
              ),
          ],
        ),
        style: DesignTokens.textBodyMd,
      ),
    );

    final bubbleRow = _isUser
        ? Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            mainAxisSize: MainAxisSize.min,
            children: [
              bubble,
              const SizedBox(width: DesignTokens.spacingBookmarkGap),
              BookmarkButton(
                status: bookmarkStatus ?? BookmarkStatus.idle,
                onTap: onBookmarkTap,
              ),
            ],
          )
        : bubble;

    return Align(
      alignment: _isUser ? Alignment.centerRight : Alignment.centerLeft,
      child: GestureDetector(
        onTap: isFailed ? onRetryTap : null,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingXs),
          child: Column(
            crossAxisAlignment: _isUser ? CrossAxisAlignment.end : CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              bubbleRow,
              const SizedBox(height: DesignTokens.spacingXs),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: DesignTokens.spacingMd),
                child: _StatusLine(message: message),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _StatusLine extends StatelessWidget {
  const _StatusLine({required this.message});

  final ChatMessage message;

  @override
  Widget build(BuildContext context) {
    switch (message.status) {
      case ChatMessageStatus.streaming:
        // Prototype: no timestamp or spinner below the bubble while
        // streaming — the only in-progress indicator is the cursor inline
        // at the end of the bubble's own text.
        return const SizedBox.shrink();
      case ChatMessageStatus.complete:
        return _TimeText(message: message);
      case ChatMessageStatus.failed:
        // Prototype: the failure note sits above the time, not in place of
        // it (both render, stacked with the same 4dp gap as the rest of
        // this column) — regular (Karla) small text, not the monospaced
        // timestamp style.
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              'Falha ao gerar resposta — toque para tentar novamente',
              style: DesignTokens.textBodyMd.copyWith(
                fontSize: 12,
                color: DesignTokens.colorError,
              ),
            ),
            const SizedBox(height: DesignTokens.spacingXs),
            _TimeText(message: message),
          ],
        );
    }
  }
}

/// Pulsing cursor appended at the end of a streaming message's text
/// (prototype-extract.md §2.2/§3: "blinking cursor at the end of the text").
class _StreamingCursor extends StatefulWidget {
  const _StreamingCursor();

  @override
  State<_StreamingCursor> createState() => _StreamingCursorState();
}

class _StreamingCursorState extends State<_StreamingCursor> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1000),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, _) {
        final opacity = 0.2 + 0.8 * (1 - (_controller.value - 0.5).abs() * 2).clamp(0.0, 1.0);
        return Opacity(
          opacity: opacity,
          child: Container(
            width: 2,
            height: DesignTokens.textBodyMd.fontSize,
            margin: const EdgeInsets.only(left: 2),
            color: DesignTokens.colorTextPrimary,
          ),
        );
      },
    );
  }
}

class _TimeText extends StatelessWidget {
  const _TimeText({required this.message});

  final ChatMessage message;

  @override
  Widget build(BuildContext context) {
    return Text(
      TimeOfDay.fromDateTime(message.createdAt.toLocal()).format(context),
      style: DesignTokens.textMonoCaption.copyWith(
        color: DesignTokens.colorTextSecondary,
      ),
    );
  }
}

