1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/chat/data/chat_local_cache.dart';
5	import 'package:cerne/features/chat/data/chat_remote_data_source.dart';
6	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_session.dart';
8	import 'package:cerne/features/chat/domain/entities/chat_sessions_page.dart';
9	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
10	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
11	import 'package:cerne/features/session/domain/repositories/session_repository.dart';
12	import 'package:fpdart/fpdart.dart';
13	
14	/// Wraps [ChatRemoteDataSource] + [ChatLocalCache] + [SessionRepository]
15	/// (for the silent-refresh retry, research.md R3) — same constructor shape
16	/// as `EntriesRepositoryImpl`. Registered as a `get_it` `lazySingleton` so
17	/// [cachedSessions]/[cachedMessages] survive across screen rebuilds.
18	class ChatRepositoryImpl implements ChatRepository {
19	  ChatRepositoryImpl(
20	    this._remoteDataSource, {
21	    required this._sessionRepository,
22	    required this._localCache,
23	  });
24	
25	  final ChatRemoteDataSource _remoteDataSource;
26	  final SessionRepository _sessionRepository;
27	  final ChatLocalCache _localCache;
28	
29	  List<ChatSession> _cachedSessions = [];
30	  final Map<String, List<ChatMessage>> _cachedMessages = {};
31	  Map<String, String> _savedMessageEntryIds = {};
32	  Future<void>? _localCacheLoad;
33	
34	  Future<void> _ensureLocalCacheLoaded() {
35	    return _localCacheLoad ??= () async {
36	      _cachedSessions = await _localCache.readSessions();
37	      _cachedMessages.addAll(await _localCache.readAllMessages());
38	      _savedMessageEntryIds = await _localCache.readSavedMessageEntryIds();
39	    }();
40	  }
41	
42	  @override
43	  Future<Either<Failure, ChatSession>> createSession({
44	    required String title,
45	  }) async {
46	    await _ensureLocalCacheLoaded();
47	    final result = await _retryAfterSilentRefreshIfExpired(
48	      () => _remoteDataSource.createSession(title: title),
49	    );
50	    return result.match((f) => Left(f), (session) {
51	      _upsertSession(session);
52	      unawaited(_localCache.writeSessions(_cachedSessions));
53	      return Right(session);
54	    });
55	  }
56	
57	  @override
58	  Future<Either<Failure, ChatSessionsPage>> listSessions({
59	    String? cursor,
60	    int? limit,
61	  }) async {
62	    await _ensureLocalCacheLoaded();
63	    final result = await _retryAfterSilentRefreshIfExpired(
64	      () => _remoteDataSource.listSessions(cursor: cursor, limit: limit),
65	    );
66	    return result.match((f) => Left(f), (page) {
67	      for (final s in page.sessions) {
68	        _upsertSession(s);
69	      }
70	      unawaited(_localCache.writeSessions(_cachedSessions));
71	      return Right(page);
72	    });
73	  }
74	
75	  @override
76	  List<ChatSession> get cachedSessions => List.unmodifiable(_cachedSessions);
77	
78	  @override
79	  Future<Either<Failure, List<ChatMessage>>> listMessages(
80	    String sessionId,
81	  ) async {
82	    await _ensureLocalCacheLoaded();
83	    final result = await _retryAfterSilentRefreshIfExpired(
84	      () => _remoteDataSource.listMessages(sessionId),
85	    );
86	    return result.match((f) => Left(f), (messages) {
87	      _cachedMessages[sessionId] = messages;
88	      unawaited(_localCache.writeMessagesForSession(sessionId, messages));
89	      return Right(messages);
90	    });
91	  }
92	
93	  @override
94	  List<ChatMessage>? cachedMessages(String sessionId) =>
95	      _cachedMessages[sessionId];
96	
97	  @override
98	  Future<void> setLastActiveSessionId(String? sessionId) =>
99	      _localCache.writeLastActiveSessionId(sessionId);
100	
101	  @override
102	  Future<String?> get lastActiveSessionId =>
103	      _localCache.readLastActiveSessionId();
104	
105	  @override
106	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
107	    required String sessionId,
108	    required String content,
109	  }) => _streamWithAuthRetry(
110	    () => _remoteDataSource.sendMessage(sessionId: sessionId, content: content),
111	  );
112	
113	  @override
114	  Stream<Either<Failure, ChatStreamEvent>> retryMessage({
115	    required String sessionId,
116	    required String userMessageId,
117	  }) => _streamWithAuthRetry(
118	    () => _remoteDataSource.retryMessage(
119	      sessionId: sessionId,
120	      userMessageId: userMessageId,
121	    ),
122	  );
123	
124	  @override
125	  String? savedEntryIdFor(String chatMessageId) =>
126	      _savedMessageEntryIds[chatMessageId];
127	
128	  @override
129	  Future<void> recordMessageSaved({
130	    required String chatMessageId,
131	    required String entryId,
132	  }) async {
133	    _savedMessageEntryIds = {..._savedMessageEntryIds, chatMessageId: entryId};
134	    await _localCache.writeSavedMessageEntryIds(_savedMessageEntryIds);
135	  }
136	
137	  /// research.md R3 — retries the whole call once, only if the *first* item
138	  /// is `AuthExpiredFailure` (i.e. before any `ChatStreamEvent` was ever
139	  /// emitted). Once any event has been emitted, a later `AuthExpiredFailure`
140	  /// is yielded as-is, no retry attempted.
141	  Stream<Either<Failure, ChatStreamEvent>> _streamWithAuthRetry(
142	    Stream<Either<Failure, ChatStreamEvent>> Function() call,
143	  ) async* {
144	    var stream = call();
145	    var canRetry = true;
146	    while (true) {
147	      var sawAnyItem = false;
148	      var restarted = false;
149	      await for (final item in stream) {
150	        if (!sawAnyItem &&
151	            canRetry &&
152	            item.match((f) => f is AuthExpiredFailure, (_) => false)) {
153	          final refreshed = await _sessionRepository.refresh();
154	          if (refreshed.isLeft()) {
155	            yield item;
156	            return;
157	          }
158	          canRetry = false;
159	          stream = call();
160	          restarted = true;
161	          break;
162	        }
163	        sawAnyItem = true;
164	        yield item;
165	      }
166	      if (!restarted) return;
167	    }
168	  }
169	
